"import { darkColors, lightColors, navyGoldColors, spacing, radius, font, ThemeType } from '@/src/theme';

type Mode = 'light' | 'dark' | 'navy_gold' | 'system';

const STORAGE_KEY = 'theme_mode';

type Ctx = {
  theme: ThemeType;
  mode: Mode;
  effective: 'light' | 'dark' | 'navy_gold';
  setMode: (m: Mode) => void;
};

const defaultCtx: Ctx = {
  theme: { color: lightColors, spacing, radius, font },
  mode: 'system',
  effective: 'light',
  setMode: () => {},
};

const ThemeContext = createContext<Ctx>(defaultCtx);

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const system = useColorScheme();
  const [mode, setModeState] = useState<Mode>('system');
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const v = (await AsyncStorage.getItem(STORAGE_KEY)) as Mode | null;
        if (v === 'light' || v === 'dark' || v === 'navy_gold' || v === 'system') setModeState(v);
      } catch { /* ignore */ }
      finally { setHydrated(true); }
    })();
    // Safety: if AsyncStorage hangs, render with defaults after 3s
    const timer = setTimeout(() => setHydrated(true), 3000);
    return () => clearTimeout(timer);
  }, []);

  const setMode = (m: Mode) => {
    setModeState(m);
    AsyncStorage.setItem(STORAGE_KEY, m).catch(() => {});
  };

  const effective: 'light' | 'dark' | 'navy_gold' = mode === 'system' ? (system === 'dark' ? 'dark' : 'light') : mode;

  const value = useMemo<Ctx>(() => ({
    theme: {
      color: effective === 'navy_gold' ? navyGoldColors : (effective === 'dark' ? darkColors : lightColors),
      spacing, radius, font,
    },
    mode, effective, setMode,
  }), [effective, mode]);"

